contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        uint256 cBefore = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Since no deposit was made, the caller's balance in c is 0.
        // Therefore withdraw(amount) should revert exactly when amount > 0.
        // Withdraw(0) succeeds and changes nothing.
        assert(
            (amount == 0 && !reverted && address(c).balance == cBefore) ||
            (amount > 0 && reverted && address(c).balance == cBefore)
        );
    }

    receive() external payable {}
}

